public class OptimizedValidationService {
    // Anti-pattern: Using exceptions for expected business logic validation
    public void validateUserBad(User user) {
        if (user == null) {
            throw new UserValidationException("User cannot be null"); // Generates heavy StackTraceElement[]
        }
    }

    // Production-grade pattern: Fast-path validation returning a Result or Optional
    public ValidationResult validateUserGood(User user) {
        if (user == null) {
            return ValidationResult.failure("User cannot be null");
        }
        return ValidationResult.success();
    }

    // High-performance exception override when stack traces are definitively unneeded
    public static class FastException extends RuntimeException {
        @Override
        public synchronized Throwable fillInStackTrace() {
            return this; // Suppresses stack trace generation entirely
        }
    }
}
